import{_ as a,o as t,c as s,a0 as i}from"./chunks/framework.bcCluOOn.js";const h=JSON.parse('{"title":"Data Types","description":"","frontmatter":{},"headers":[],"relativePath":"specification/types.md","filePath":"specification/types.md"}'),o={name:"specification/types.md"};function n(l,e,p,d,c,r){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="data-types" tabindex="-1">Data Types <a class="header-anchor" href="#data-types" aria-label="Permalink to &quot;Data Types&quot;">​</a></h1><p>AAYU provides a set of strong, built-in data types tailored for building modern software applications.</p><h2 id="primitive-types" tabindex="-1">Primitive Types <a class="header-anchor" href="#primitive-types" aria-label="Permalink to &quot;Primitive Types&quot;">​</a></h2><h3 id="text" tabindex="-1"><code>text</code> <a class="header-anchor" href="#text" aria-label="Permalink to &quot;`text`&quot;">​</a></h3><p>Represents a string of characters. Text literals are enclosed in double quotes.</p><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>text name is &quot;AAYU Developer&quot;.</span></span></code></pre></div><h3 id="number" tabindex="-1"><code>number</code> <a class="header-anchor" href="#number" aria-label="Permalink to &quot;`number`&quot;">​</a></h3><p>Represents numeric values. AAYU&#39;s <code>number</code> type handles both integers and floating-point values seamlessly.</p><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>number count is 10.</span></span>\n<span class="line"><span>number price is 19.99.</span></span></code></pre></div><h3 id="boolean" tabindex="-1"><code>boolean</code> <a class="header-anchor" href="#boolean" aria-label="Permalink to &quot;`boolean`&quot;">​</a></h3><p>Represents a truth value, either <code>true</code> or <code>false</code>.</p><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>boolean is_admin is true.</span></span></code></pre></div><h2 id="collection-types" tabindex="-1">Collection Types <a class="header-anchor" href="#collection-types" aria-label="Permalink to &quot;Collection Types&quot;">​</a></h2><h3 id="list" tabindex="-1"><code>list</code> <a class="header-anchor" href="#list" aria-label="Permalink to &quot;`list`&quot;">​</a></h3><p>An ordered collection of items. Lists can contain items of mixed types, though homogenous lists are recommended.</p><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>list tags is [&quot;urgent&quot;, &quot;backend&quot;, &quot;v1&quot;].</span></span></code></pre></div><p>You can access list items using the <code>at</code> keyword (0-indexed).</p><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>text first_tag is tags at 0.</span></span></code></pre></div><h3 id="map" tabindex="-1"><code>map</code> <a class="header-anchor" href="#map" aria-label="Permalink to &quot;`map`&quot;">​</a></h3><p>A key-value data structure, equivalent to an object in JSON or a dictionary in Python.</p><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>map user_data.</span></span>\n<span class="line"><span>set &quot;username&quot; to &quot;alice&quot; in user_data.</span></span>\n<span class="line"><span>set &quot;role&quot; to &quot;admin&quot; in user_data.</span></span></code></pre></div><p>Values can be retrieved using the <code>get</code> keyword.</p><div class="language-aayu vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">aayu</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>text username is get &quot;username&quot; from user_data.</span></span></code></pre></div><h2 id="future-type-extensions" tabindex="-1">Future Type Extensions <a class="header-anchor" href="#future-type-extensions" aria-label="Permalink to &quot;Future Type Extensions&quot;">​</a></h2><p>As the AAYU specification evolves, the following types are planned for native integration to support robust database and API modeling:</p><ul><li><code>uuid</code>: A universally unique identifier.</li><li><code>date</code> / <code>datetime</code>: Native representations of time and duration.</li><li><code>email</code>: A validated email string type.</li><li><code>file</code>: A representation of uploaded binary data.</li></ul>',26)])])}const b=a(o,[["render",n]]);export{h as __pageData,b as default};
